    }

    /**
     * 为指定 FAIL 核查写入逐结果隔离标记（幂等，重复不报错）。
     */
    public void insertIgnore(long measurementId, long checkId, Instant createdAt) {
        jdbc.update("INSERT IGNORE INTO measurement_suspect "
                        + "(measurement_id, check_id, cleared, created_at) VALUES (?, ?, FALSE, ?)",
                measurementId, checkId, JdbcTimes.toDb(createdAt));
    }

